syntax:
template <typename T> struct remove_pointer {
    using type = T; // default case
};
template <typename T> struct remove_pointer<T*> {
    using type = T; // specialization for pointer types
};

template <typename T> using remove_pointer_t = typename remove_pointer<T>::type;

// Similar pattern applies for add_pointer, remove_reference, etc.

code_example:
#include <iostream>
template <typename T> struct remove_pointer {
    using type = T;
};
template <typename T> struct remove_pointer<T*> {
    using type = T;
};
template <typename T> using remove_pointer_t = typename remove_pointer<T>::type;

int main() {
    using T1 = int*;
    using T2 = remove_pointer_t<T1>;
    static_assert(std::is_same<T2, int>::value, "Type should be int");
    std::cout << "remove_pointer_t<int*> is int" << std::endl;
    return 0;
}
